"use strict";

const { parseYamlBlock } = require("../parse.js");

/**
 * Extract YAML frontmatter from markdown content.
 * Returns parsed frontmatter object or null if no frontmatter found.
 */
function extract(content) {
  const match = content.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!match) return null;
  return parseYamlBlock(match[1]);
}

/**
 * Apply predicate changes to markdown file content.
 * Text-edits existing YAML frontmatter in place.
 *
 * Counit law: extract(apply(changes, content)) must equal
 * the original predicates with changes applied.
 *
 * @param {Array<{key: string, from?: string, to: string|string[]|null}>} changes
 * @param {string} content - Full file content including frontmatter and body
 * @returns {{content: string, error?: string}} - Modified content or error
 */
function apply(changes, content) {
  const fmMatch = content.match(/^(---\r?\n)([\s\S]*?)(\r?\n---)([\s\S]*)$/);
  if (!fmMatch) {
    return { content, error: "no-frontmatter" };
  }

  const openDelim = fmMatch[1];
  let fmText = fmMatch[2];
  const closeDelim = fmMatch[3];
  const body = fmMatch[4];
  const fmLines = fmText.split(/\r?\n/);

  const errors = [];

  for (const change of changes) {
    const { key, from, to } = change;

    // Find the line index for this key
    const lineIdx = findKeyLine(fmLines, key);

    if (lineIdx === -1) {
      // Key not found
      if (to === null || to === undefined) continue; // deleting something absent — no-op
      // Addition: append before end of frontmatter
      const newLine = serializeKeyValue(key, to);
      fmLines.push(newLine);
      continue;
    }

    // Key found — check conflict if from is specified
    if (from !== undefined) {
      const currentVal = extractValueAtLine(fmLines, lineIdx);
      if (!valuesMatch(currentVal, from)) {
        errors.push(`conflict: ${key} expected "${from}" but found "${currentVal}"`);
        continue;
      }
    }

    if (to === null || to === undefined) {
      // Deletion: remove key line and any continuation lines
      const endIdx = findBlockEnd(fmLines, lineIdx);
      fmLines.splice(lineIdx, endIdx - lineIdx);
      continue;
    }

    // Replacement: determine the original style and match it
    replaceValueAtLine(fmLines, lineIdx, to);
  }

  if (errors.length > 0) {
    return { content, error: errors.join("; ") };
  }

  const newContent = openDelim + fmLines.join("\n") + closeDelim + body;
  return { content: newContent };
}

/**
 * Find the line index where a key is defined.
 * Returns -1 if not found.
 */
function findKeyLine(lines, key) {
  const escaped = key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp("^" + escaped + ":\\s*");
  for (let i = 0; i < lines.length; i++) {
    if (re.test(lines[i])) return i;
  }
  return -1;
}

/**
 * Extract the current value at a given key line.
 * Handles inline scalars, inline arrays, and multi-line lists.
 */
