{"command":"node -e "
const { extract, apply } = require('./operations/engineering/systems/fars/filetypes/markdown.js');
const fs = require('fs');

// Test against a real file
const content = fs.readFileSync('library/domains/humanities/domains/sociology/domains/work/terms/plan.md', 'utf8');
const before = extract(content);
console.log('Before - type:', before.type, 'status:', before.readiness);
console.log('Before - extends:', before.extends);
console.log('Before - has:', before.has);

// Apply changes
const result = apply([
  { key: 'readiness', from: 'shaped', to: 'enriched' },
  { key: 'date-modified', to: '2026-04-06' },
], content);

if (result.error) { console.log('ERROR:', result.error); process.exit(1); }

const after = extract(result.content);
console.log('After - readiness:', after.readiness);
console.log('After - date-modified:', after['date-modified']);
console.log('After - extends still there:', after.extends);
console.log('After - has still there:', after.has);
console.log('Body preserved:', result.content.includes('# Plan'));
console.log('Counit: readiness changed:', after.readiness === 'enriched');
console.log('Counit: other keys preserved:', after.type === 'term' && after.title === 'Plan');
"
","description":"Test apply() against real repo file"}

