{"file_path":"/home/emsenn/561/operations/engineering/systems/foah/compile-constraints.js","content":"/**
 * ---
 * id: foah-compile-constraints
 * type: module
 * part-of: foah
 * exports: [compileConstraints, loadConstraintCache]
 * description: "Compile constraint entities into a fast-lookup cache. The cache is the precompiled fiber — entity data in a format the stepping map can evaluate in <1ms."
 * ---
 *
 * Reads all entities with type: constraint from the knowledge graph,
 * groups them by applies-to tool, and writes a JSON cache file.
 * Hooks load the cache instead of the full graph.
 *
 * This is the DF raws pattern: data-driven rules, generic engine.
 * The constraint entities are the raws. This script compiles them.
 * The hook's stepping map evaluates the compiled result.
 */
"use strict";

const fs = require("fs");
const path = require("path");

const REPO_ROOT = path.resolve(__dirname, "../../../..");
const CACHE_PATH = path.join(REPO_ROOT, "operations/engineering/systems/foah/constraint-cache.json");

/**
 * Compile constraint entities from the knowledge graph into a cache.
 * @param {object} db - The loaded EAVT graph
 * @returns {object} Cache grouped by applies-to tool
 */
function compileConstraints(db) {
  const cache = {};

  // Find all entities with type: constraint
  const constraintEids = [];
  if (db.byValue) {
    const typeConstraint = db.byValue.get("constraint");
    if (typeConstraint) {
      for (const eid of typeConstraint) {
        constraintEids.push(eid);
      }
    }
  }

  for (const eid of constraintEids) {
    const triples = db.byEntity.get(eid);
    if (!triples) continue;

    // Extract predicates from triples
    const entity = {};
    for (const [aid, val] of triples) {
      // We need attr names — look them up from the aid
      // The db doesn't expose attrs directly, so we scan for known predicates by value
      entity[aid] = val;
    }

    // Build constraint from known predicate values
    const constraint = { eid };
    let appliesTo = null;

    for (const [aid, val] of triples) {
      if (typeof val !== "string") continue;
      // Match by value patterns since we can't resolve attr names from db easily
      // Instead, let's read the source files directly
    }
  }

  // Alternative: read constraint files directly from the constraints/ directory
  // This is simpler and avoids the attr-name resolution problem
  const constraintDir = path.join(REPO_ROOT, "operations/engineering/systems/foah/constraints");
  if (!fs.existsSync(constraintDir)) return cache;

  const { parseFrontmatter } = require("../fars/parse.js");

  for (const file of fs.readdirSync(constraintDir)) {
    if (!file.endsWith(".md")) continue;
    const content = fs.readFileSync(path.join(constraintDir, file), "utf8");
    const fm = parseFrontmatter(content);
    if (!fm || fm.type !== "constraint") continue;

    const tool = fm["applies-to"] || "unknown";
    if (!cache[tool]) cache[tool] = [];

    cache[tool].push({
      id: fm.id || file.replace(".md", ""),
      pattern: fm.pattern,
      action: fm.action || "block",
      severity: fm.severity || "medium",
      reason: fm.reason || "",
      alternative: fm.alternative || null,
      category: fm.category || "general",
    });
  }

  return cache;
}

/**
 * Write the compiled cache to disk.
 */
function writeCache(cache) {
  fs.writeFileSync(CACHE_PATH, JSON.stringify(cache, null, 2), "utf8");
  return CACHE_PATH;
}

/**
 * Load the constraint cache. Returns the cached data or compiles fresh if missing.
 */
function loadConstraintCache() {
  try {
    if (fs.existsSync(CACHE_PATH)) {
      return JSON.parse(fs.readFileSync(CACHE_PATH, "utf8"));
    }
  } catch (e) {
    // Cache corrupted or missing — recompile
  }
  const cache = compileConstraints(null);
  writeCache(cache);
  return cache;
}

module.exports = { compileConstraints, loadConstraintCache, writeCache, CACHE_PATH };

if (require.main === module) {
  const cache = compileConstraints(null);
  const cachePath = writeCache(cache);
  const total = Object.values(cache).reduce((n, arr) => n + arr.length, 0);
  const tools = Object.keys(cache);
  process.stdout.write(`Compiled ${total} constraints for ${tools.length} tools: ${tools.join(", ")}\n`);
  process.stdout.write(`Cache written to: ${cachePath}\n`);
}
"}

