 * Test the constraint cache: load it, compile regexes, test against sample commands.
 */
"use strict";

const { loadConstraintCache } = require("./compile-constraints.js");

const cache = loadConstraintCache();
let pass = 0;
let fail = 0;

function test(constraintId, command, shouldMatch) {
  const constraints = cache.Bash || [];
  const c = constraints.find(x => x.id === constraintId);
  if (!c) { console.log(`✗ ${constraintId}: not found in cache`); fail++; return; }

  try {
    const re = new RegExp(c.pattern);
    const matched = re.test(command);
    if (matched === shouldMatch) {
      pass++;
    } else {
      console.log(`✗ ${constraintId}: "${command}" expected ${shouldMatch ? "match" : "no match"} but got ${matched ? "match" : "no match"}`);
      fail++;
    }
  } catch (e) {
    console.log(`✗ ${constraintId}: regex error: ${e.message}`);
    fail++;
  }
}

// Test destructive pattern matching
test("block-rm-rf-critical-path", "rm -rf /home/user", true);
test("block-rm-rf-critical-path", "rm -rf ~/docs", true);
test("block-rm-rf-critical-path", "rm file.txt", false);
test("block-rm-rf-critical-path", "ls -la /home", false);

// Test tool-bypass matching
test("redirect-grep-to-tool", "grep foo bar.txt", true);
test("redirect-grep-to-tool", "echo hello", false);
test("redirect-grep-to-tool", "node -e 'console.log(1)'", false);

console.log(`\n${pass} passed, ${fail} failed, ${pass + fail} total`);
process.exit(fail > 0 ? 1 : 0);
"}

