 * ---
 *
 * General-purpose cache compiler for hot-path access to entity subsets.
 * Instead of loading the full 47K-entity graph, hooks and tools can
 * read a small precompiled cache for their specific entity type.
 *
 * Usage:
 *   compileCache({
 *     filter: { type: "constraint" },
 *     groupBy: "applies-to",
 *     fields: ["id", "pattern", "action", "severity", "reason", "alternative", "category"],
 *     defaults: { action: "block", severity: "medium" },
 *     sources: ["operations/engineering/systems/foah/constraints"],
 *   })
 *
 * Can also scan the full graph by walking directories that generate.js walks.
 */
"use strict";

const fs = require("fs");
const path = require("path");

const REPO_ROOT = path.resolve(__dirname, "../../../..");
const CACHE_DIR = path.join(REPO_ROOT, "operations/engineering/systems/fars/caches");

const { parseFrontmatter } = require("./parse.js");

/**
 * Compile a cache from entity files matching a filter.
 *
 * @param {object} opts
 * @param {object} opts.filter - Key-value pairs to match in frontmatter (all must match)
 * @param {string} [opts.groupBy] - Field to group results by. If omitted, returns flat array.
 * @param {string[]} opts.fields - Fields to extract from each entity
 * @param {object} [opts.defaults] - Default values for missing fields
 * @param {string[]} opts.sources - Directories to scan for entity files
 * @returns {object|array} Grouped object or flat array of entities
 */
function compileCache(opts) {
  const { filter, groupBy, fields, defaults = {}, sources } = opts;
  const results = groupBy ? {} : [];

  for (const dir of sources) {
    const absDir = path.isAbsolute(dir) ? dir : path.join(REPO_ROOT, dir);
    if (!fs.existsSync(absDir)) continue;

    walkDir(absDir, (filePath) => {
      if (!filePath.endsWith(".md")) return;

      const content = fs.readFileSync(filePath, "utf8");
      const fm = parseFrontmatter(content);
      if (!fm) return;

      // Check filter
      for (const [key, val] of Object.entries(filter)) {
        if (fm[key] !== val) return;
      }

      // Extract fields
      const entity = {};
      for (const field of fields) {
        entity[field] = fm[field] !== undefined ? fm[field] : (defaults[field] || null);
      }

      // Ensure id
      if (!entity.id && fm.id) entity.id = fm.id;
      if (!entity.id) entity.id = path.basename(filePath, ".md");

      if (groupBy) {
        const groupVal = fm[groupBy] || "unknown";
        if (!results[groupVal]) results[groupVal] = [];
        results[groupVal].push(entity);
      } else {
        results.push(entity);
      }
    });
  }

  return results;
}

/**
 * Walk a directory recursively, calling fn on each file.
 */
function walkDir(dir, fn) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walkDir(fullPath, fn);
    } else {
      fn(fullPath);
    }
  }
}

/**
 * Write a compiled cache to disk.
 * @param {string} name - Cache name (used as filename)
 * @param {object|array} data - Compiled cache data
 * @returns {string} Path to written cache file
 */
function writeCacheToDisk(name, data) {
  if (!fs.existsSync(CACHE_DIR)) fs.mkdirSync(CACHE_DIR, { recursive: true });
  const cachePath = path.join(CACHE_DIR, name + ".json");
  fs.writeFileSync(cachePath, JSON.stringify(data, null, 2), "utf8");
  return cachePath;
}

/**
 * Load a named cache from disk. Returns null if not found.
 * @param {string} name - Cache name
 * @returns {object|array|null}
 */
function loadCache(name) {
  const cachePath = path.join(CACHE_DIR, name + ".json");
  try {
    if (fs.existsSync(cachePath)) {
      return JSON.parse(fs.readFileSync(cachePath, "utf8"));
    }
  } catch (e) {
    // Cache corrupted — caller should recompile
  }
  return null;
}

